import type { Field, QsScores, Region, Selectivity, University } from "@/lib/types";
import raw from "./research/qs2027-all.json";
import { P, type Preset } from "./universities-world";
import { U } from "./universities-extra";

/*
 * The full QS World University Rankings 2027 list (1,504 institutions), read from topuniversities.com
 * on 3 Nov 2026. Names, locations, ranks and indicator scores come from QS. Everything else on these
 * "basic" profiles (descriptions, typical costs, requirements) is generated by CareerPath from the
 * country's system and marked unverified — students should confirm on the university's own site.
 */

type Row = [slug: string, name: string, country: string, city: string, region: Region, display: string, rank: number, overall: number | null, ar: number | null, er: number | null, fsr: number | null, isr: number | null, eo: number | null, sus: number | null, cpf: number | null, lat: number | null, lng: number | null, curated: string | null];
const ROWS = raw as unknown as Row[];

export const QS_URL = "https://www.topuniversities.com/world-university-rankings";

const scores = (r: Row): QsScores => ({ overall: r[7], academicReputation: r[8], employerReputation: r[9], facultyStudent: r[10], internationalStudents: r[11], employmentOutcomes: r[12], sustainability: r[13], citations: r[14] });

/** QS data for curated CareerPath universities, keyed by our slug. */
export const QS_FOR_CURATED = new Map(ROWS.filter((r) => r[17]).map((r) => [r[17]!, { display: r[5], rank: r[6], qs: scores(r), qsUrl: `https://www.topuniversities.com/universities/${r[0]}` }]));

const COUNTRY_PRESET: Record<string, keyof typeof P> = {
  "United States": "USPUB", "United Kingdom": "UK", Canada: "CA", Australia: "AU", "New Zealand": "NZ", Ireland: "UK",
  China: "CN", "Hong Kong SAR": "CN", "Macao SAR": "CN", Japan: "JP", Taiwan: "TW", India: "IN", Pakistan: "IN", Bangladesh: "IN", "Sri Lanka": "IN",
  Malaysia: "MY", Thailand: "MY", Philippines: "MY", Vietnam: "MY", Indonesia: "ID", Brunei: "MY", Singapore: "MY",
  Spain: "ES", Mexico: "LATAM", Brazil: "LATAM", Argentina: "LATAM", Chile: "LATAM", Colombia: "LATAM", Peru: "LATAM", Ecuador: "LATAM", Venezuela: "LATAM", Uruguay: "LATAM", "Costa Rica": "LATAM", Cuba: "LATAM", Panama: "LATAM", "Puerto Rico": "LATAM", Bolivia: "LATAM", Paraguay: "LATAM", Guatemala: "LATAM", "Dominican Republic": "LATAM",
  "South Africa": "ZA", Egypt: "ZA", Nigeria: "ZA", Kenya: "ZA", Ghana: "ZA", Ethiopia: "ZA", Uganda: "ZA", Tanzania: "ZA", Morocco: "ZA", Tunisia: "ZA", Algeria: "ZA", Rwanda: "ZA", Zimbabwe: "ZA", Botswana: "ZA", Namibia: "ZA", Mauritius: "ZA",
  "Saudi Arabia": "GULF", "United Arab Emirates": "GULF", Qatar: "GULF", Kuwait: "GULF", Bahrain: "GULF", Oman: "GULF",
  Netherlands: "EU_FEE", Sweden: "EU_FEE", Denmark: "EU_FEE", Finland: "EU_FEE", Norway: "EU_FEE", Switzerland: "EU_LOW", Belgium: "EU_FEE", "Türkiye": "EU_FEE",
};
// Low-tuition public systems (Germany, Austria, Czechia, Poland, Russia, Central Asia, etc.) fall back to EU_LOW.

const LOCAL: Record<string, Preset> = {
  "Central Asia": { tuition: ["under-5k", "Contract tuition varies by programme — confirm with the university"], aid: ["government", "State grants and bilateral scholarships for some students."], eng: { note: "Language of instruction varies (Uzbek, Kazakh, Russian, English) — confirm." }, test: ["required", "National or university entrance exams usually apply."], dl: P.EU_LOW.dl },
};

function fieldsFor(name: string): Field[] {
  const n = name.toLowerCase();
  if (/medic|health|pharma|nursing|dental/.test(n)) return ["medicine-health", "natural-sciences"];
  if (/agricult|agrar|veterin|forestr|irrigation/.test(n)) return ["environment", "natural-sciences", "engineering", "economics"];
  if (/econom|business|management|commerce|finance|trade/.test(n)) return ["business", "economics", "finance", "data-science"];
  if (/pedagog|education|teacher/.test(n)) return ["education", "humanities", "social-sciences"];
  if (/\barts?\b|music|design|fine arts/.test(n)) return ["arts-design", "humanities", "media-communications"];
  if (/law\b|legal/.test(n)) return ["law", "politics-ir", "social-sciences"];
  if (/technolog|technical|polytechn|engineering|science and technology|institute of technology|tech\b|mining|petroleum|aviation|transport/.test(n)) return ["engineering", "computer-science", "mathematics", "natural-sciences", "data-science"];
  return ["business", "economics", "engineering", "computer-science", "natural-sciences", "social-sciences", "humanities", "medicine-health", "law"];
}

const selectivity = (rank: number): Selectivity => (rank <= 30 ? "most" : rank <= 250 ? "high" : rank <= 800 ? "moderate" : "accessible");

const STRENGTHS: [keyof QsScores, string][] = [
  ["academicReputation", "academic reputation"],
  ["employerReputation", "reputation with employers"],
  ["employmentOutcomes", "graduate employment outcomes"],
  ["facultyStudent", "faculty-to-student ratio"],
  ["internationalStudents", "share of international students"],
  ["sustainability", "sustainability"],
  ["citations", "research citations"],
];

function overview(r: Row, kind: string) {
  const q = scores(r);
  const top = STRENGTHS.filter(([k]) => (q[k] ?? 0) >= 60).sort((a, b) => (q[b[0]] ?? 0) - (q[a[0]] ?? 0)).slice(0, 2).map(([, l]) => l);
  const rankText = /[-+]/.test(r[5]) ? `in the ${r[5].replace("-", "–")} band` : `#${r[5].replace("=", "")}${r[5].startsWith("=") ? " (joint)" : ""}`;
  return `${kind} in ${r[3] ? `${r[3]}, ` : ""}${r[2]}, ranked ${rankText} in the QS World University Rankings 2027.${top.length ? ` Its strongest QS indicators are ${top.join(" and ")}.` : ""}`;
}

const shortFrom = (name: string) => name.match(/\(([^)]{2,14})\)\s*$/)?.[1];
const clean = (name: string) => name.replace(/\s*\([^)]{2,14}\)\s*$/, "").trim();

/** Basic profiles for every QS-ranked university not already in CareerPath's researched set. */
export function qsBasicUniversities(existing: Set<string>): (University & { geo?: [number, number] })[] {
  const out: (University & { geo?: [number, number] })[] = [];
  for (const r of ROWS) {
    if (r[17] || existing.has(r[0])) continue;
    const name = clean(r[1]);
    const kind = /institute|school|college|academy/i.test(name) && !/university/i.test(name) ? "An institution" : "A university";
    const preset = r[4] === "Central Asia" ? LOCAL["Central Asia"] : P[COUNTRY_PRESET[r[2]] ?? "EU_LOW"];
    const qsUrl = `https://www.topuniversities.com/universities/${r[0]}`;
    const u = U({
      slug: r[0], name, short: shortFrom(r[1]), country: r[2], cc: "", city: r[3] || r[2], region: r[4], site: qsUrl, adm: qsUrl,
      overview: overview(r, kind), fields: fieldsFor(name), programs: [], sel: selectivity(r[6]),
      lang: preset.lang, levels: preset.levels, tuition: preset.tuition, aid: [preset.aid[0], preset.aid[1], qsUrl], eng: preset.eng, test: preset.test, dl: preset.dl(qsUrl), platform: preset.platform,
      intl: "This is a basic profile built from QS rankings data. Check programmes, fees, language and entry requirements on the university's official website before applying.",
    });
    // sources for generated facts point to the QS profile and are labelled as estimates, not official pages
    const est = (src: { status: "verified" | "indicative" | "unverified" }) => ({ ...src, org: `Typical for ${r[2]} — CareerPath estimate`, url: qsUrl, status: "unverified" as const });
    u.tuition.source = est(u.tuition.source);
    u.aid.source = est(u.aid.source);
    u.english.source = est(u.english.source);
    u.testing.source = est(u.testing.source);
    u.deadlines = u.deadlines.map((d) => ({ ...d, source: est(d.source) }));
    if (!preset.lang) u.languageOfInstruction = "Varies — confirm with the university";
    out.push({ ...u, qsRank: r[6], qsDisplay: r[5], qs: scores(r), profile: "basic", qsUrl, ...(r[15] != null && r[16] != null ? { geo: [r[15], r[16]] as [number, number] } : {}) });
  }
  return out;
}
